    def floyd_warshall(graph):
        dist = defaultdict(dict)
        for node in graph:
            dist[node] = {node: 0}
            for neighbor, weight in graph[node]:
                dist[node][neighbor] = weight
                dist[neighbor] = {neighbor: 0}

