def shortest_path(graph, source, target):
    """
    Finds the shortest path between source and target in a weighted graph.

    :param graph: A dictionary where keys are nodes and values are lists of (neighbour, weight) tuples.
    :param source: The start node of the path.
    :param target: The end node of the path.
    :return: A tuple (distance, path) where distance is the shortest path's cost, and path is a list of nodes.
             Returns (float("inf"), None) if the target is unreachable from the source.
    """
    if target not in graph:
        return float('inf'), None

    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    parents = {node: None for node in graph}
    distances[source] = 0
    visited = set()

    from heapq import heappop, heappush

    def dijkstra():
        while graph:
            current_node = min(graph, key=lambda node: distances[node])
            if distances[current_node] == float('inf'):
                break
            visited.add(current_node)
            graph.pop(current_node)

            for neighbour, weight in graph.get(current_node, []):
                if neighbour in visited:
                    continue

                new_distance = distances[current_node] + weight
                if new_distance < distances[neighbour]:
                    distances[neighbour] = new_distance
                    parents[neighbour] = current_node
                    heappush(graph, (new_distance, neighbour))

    dijkstra()

    path = []
    current_node = target
    while current_node is not None:
        path.insert(0, current_node)
        current_node = parents.get(current_node)

    if path[0] != source:
        path = None
    elif distances[target] == float('inf'):
        path = None

    return (distances[target], path)

